from dataclasses import dataclass
from typing import List, Tuple

@dataclass
class Student:
    name: str
    age: int
    score: float

class StudentRoster:
    def __init__(self):
        self.students: List[Student] = []

    def add_student(self, name: str, age: int, score: float) -> None:
        self.students.append(Student(name, age, score))

    def average_score(self) -> float:
        if not self.students:
            return 0.0
        return sum(student.score for student in self.students) / len(self.students)

    def top_students(self, n: int) -> List[Tuple[str, int, float]]:
        sorted_students = sorted(
            (student.score, student.name, student.age)
            for student in self.students,
            reverse=True
        )
        return [(name, age, score) for score, name, age in sorted_students[:n]]
